-- AapdaSaathi core schema (PostgreSQL 15+ / Supabase, PostGIS 3).
-- Mirrors worker/app/models/__init__.py; worker/tests/test_schema_parity.py checks they stay in sync.
-- IDs are UUID strings generated by the backend (varchar(36)) so the same code runs on SQLite for demos.

create extension if not exists postgis;

-- ----------------------------------------------------------------------------- people
create table users (
  id varchar(36) primary key,
  auth_user_id varchar(64) unique,                  -- Supabase auth.users.id when AUTH_MODE=supabase
  full_name varchar(120) not null,
  phone varchar(20) unique,
  email varchar(200) unique,
  role varchar(20) not null
    constraint ck_users_role check (role in ('resident','caregiver','neighbour','volunteer','admin','operator')),
  password_hash varchar(255),
  language varchar(5) not null default 'en',
  is_demo boolean not null default false,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

create table otp_challenges (
  id varchar(36) primary key,
  phone varchar(20) not null,
  code_hash varchar(128) not null,
  attempts integer not null default 0,
  expires_at timestamptz not null,
  consumed_at timestamptz,
  created_at timestamptz not null default now()
);
create index ix_otp_challenges_phone on otp_challenges (phone);

-- ----------------------------------------------------------------------------- geography
create table wards (
  id varchar(36) primary key,
  code varchar(40) not null unique,
  name varchar(120) not null,
  district varchar(80) not null,
  state varchar(80) not null,
  lgd_district_code varchar(10),
  boundary_geojson jsonb not null,                   -- GeoJSON Polygon/MultiPolygon, [lon, lat]
  geom geometry(Geometry, 4326)
    generated always as (st_setsrid(st_geomfromgeojson(boundary_geojson::text), 4326)) stored,
  centroid_lat double precision not null,
  centroid_lng double precision not null,
  access_status varchar(12) not null default 'open'
    constraint ck_wards_access check (access_status in ('open','restricted','blocked')),
  access_note text,
  is_demo boolean not null default false,
  created_at timestamptz not null default now(),
  constraint ck_wards_geometry_type check (geometrytype(geom) in ('POLYGON','MULTIPOLYGON'))
);
create index ix_wards_geom on wards using gist (geom);
create index ix_wards_lgd_district_code on wards (lgd_district_code);

create table shelters (
  id varchar(36) primary key,
  ward_id varchar(36) not null references wards(id) on delete cascade,
  name varchar(160) not null,
  address text not null,
  lat double precision not null,
  lng double precision not null,
  source varchar(160) not null,                      -- official designation; never generated
  is_demo boolean not null default false,
  created_at timestamptz not null default now()
);
create index ix_shelters_ward_id on shelters (ward_id);

-- ----------------------------------------------------------------------------- registry
create table residents (
  id varchar(36) primary key,
  user_id varchar(36) unique references users(id) on delete set null,
  full_name varchar(120) not null,
  phone varchar(20),
  ward_id varchar(36) not null references wards(id),
  language varchar(5) not null default 'hi',
  needs jsonb not null default '[]'::jsonb,          -- accessibility needs, never diagnoses
  lives_alone boolean not null default false,
  has_smartphone boolean not null default true,
  coarse_lat double precision,                       -- ~110 m grid only
  coarse_lng double precision,
  registration_status varchar(20) not null default 'active'
    constraint ck_residents_reg_status check (registration_status in ('active','expired','withdrawn')),
  registered_via varchar(20) not null default 'self',
  reverify_due_at timestamptz,
  is_demo boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index ix_residents_phone on residents (phone);
create index ix_residents_ward_id on residents (ward_id);

-- Exact coordinates are kept apart from the registry and guarded by RLS + audited API access.
create table resident_locations (
  id varchar(36) primary key,
  resident_id varchar(36) not null unique references residents(id) on delete cascade,
  lat double precision not null,
  lng double precision not null,
  address_text text,
  landmark text,
  source varchar(20) not null default 'registration',
  updated_at timestamptz not null default now()
);

create table consent_records (
  id varchar(36) primary key,
  resident_id varchar(36) not null references residents(id) on delete cascade,
  consent_type varchar(30) not null
    constraint ck_consent_type check (consent_type in ('registry','location','caregiver_share','sms')),
  granted boolean not null,
  granted_by varchar(20) not null constraint ck_consent_by check (granted_by in ('self','guardian','assisted')),
  guardian_name varchar(120),
  recorded_by_user_id varchar(36) references users(id) on delete set null,
  granted_at timestamptz not null default now(),
  expires_at timestamptz not null,
  withdrawn_at timestamptz
);
create index ix_consent_records_resident_id on consent_records (resident_id);

create table caregiver_links (
  id varchar(36) primary key,
  caregiver_user_id varchar(36) not null references users(id) on delete cascade,
  resident_id varchar(36) not null references residents(id) on delete cascade,
  relationship varchar(40) not null default 'family',
  can_view_location boolean not null default false,
  created_at timestamptz not null default now(),
  unique (caregiver_user_id, resident_id)
);
create index ix_caregiver_links_caregiver_user_id on caregiver_links (caregiver_user_id);
create index ix_caregiver_links_resident_id on caregiver_links (resident_id);

create table neighbour_links (
  id varchar(36) primary key,
  resident_id varchar(36) not null references residents(id) on delete cascade,
  neighbour_user_id varchar(36) not null references users(id) on delete cascade,
  priority integer not null default 1,
  distance_m double precision,
  created_at timestamptz not null default now(),
  unique (resident_id, neighbour_user_id)
);
create index ix_neighbour_links_resident_id on neighbour_links (resident_id);
create index ix_neighbour_links_neighbour_user_id on neighbour_links (neighbour_user_id);

create table volunteers (
  id varchar(36) primary key,
  user_id varchar(36) not null unique references users(id) on delete cascade,
  ward_id varchar(36) references wards(id) on delete set null,
  is_available boolean not null default true,
  base_lat double precision not null,
  base_lng double precision not null,
  max_radius_m double precision not null default 3000,
  skills jsonb not null default '[]'::jsonb,
  verified boolean not null default true,
  is_demo boolean not null default false,
  updated_at timestamptz not null default now()
);
create index ix_volunteers_ward_id on volunteers (ward_id);

create table pre_assigned_helpers (
  id varchar(36) primary key,
  resident_id varchar(36) not null references residents(id) on delete cascade,
  volunteer_id varchar(36) not null references volunteers(id) on delete cascade,
  priority integer not null default 1,
  created_at timestamptz not null default now(),
  unique (resident_id, volunteer_id)
);
create index ix_pre_assigned_helpers_resident_id on pre_assigned_helpers (resident_id);
create index ix_pre_assigned_helpers_volunteer_id on pre_assigned_helpers (volunteer_id);

-- ----------------------------------------------------------------------------- SACHET / CAP
create table feed_state (
  url varchar(400) primary key,
  etag varchar(200),
  last_modified varchar(100),
  last_fetch_at timestamptz,
  last_success_at timestamptz,
  last_status_code integer,
  last_error text,
  consecutive_failures integer not null default 0,
  next_fetch_at timestamptz,
  items_seen integer not null default 0
);

create table cap_messages (
  id varchar(36) primary key,
  identifier varchar(200) not null unique,
  feed_guid varchar(100),
  feed_url varchar(400),
  official_url varchar(400),
  sender varchar(200),
  sent timestamptz,
  status varchar(20),
  msg_type varchar(20),
  references_raw text,
  event varchar(200),
  severity varchar(20),
  urgency varchar(20),
  certainty varchar(20),
  onset timestamptz,
  expires timestamptz,
  headline text,
  area_desc text,
  raw_xml text not null,                             -- original official XML, never modified
  parsed jsonb not null default '{}'::jsonb,
  is_valid boolean not null default true,
  validation_errors jsonb not null default '[]'::jsonb,
  superseded_by varchar(200),
  is_fixture boolean not null default false,
  fetched_at timestamptz not null default now()
);
create index ix_cap_messages_feed_guid on cap_messages (feed_guid);

-- ----------------------------------------------------------------------------- incidents
create table demo_sessions (
  id varchar(36) primary key,
  started_by_user_id varchar(36) references users(id) on delete set null,
  scenario varchar(60) not null,
  started_at timestamptz not null default now(),
  reset_at timestamptz
);

create table incidents (
  id varchar(36) primary key,
  title varchar(300) not null,
  hazard_type varchar(60) not null,
  source varchar(20) not null
    constraint ck_incidents_source check (source in ('live','replay','simulated','exercise','manual')),
  status varchar(20) not null default 'active'
    constraint ck_incidents_status check (status in ('active','closed','cancelled')),
  is_demo boolean not null default false,
  demo_session_id varchar(36) references demo_sessions(id) on delete set null,
  cap_message_id varchar(36) references cap_messages(id) on delete set null,
  cap_identifier varchar(200),
  cap_sender varchar(200),
  severity varchar(20) not null default 'Unknown',
  urgency varchar(20) not null default 'Unknown',
  certainty varchar(20) not null default 'Unknown',
  sent timestamptz,
  effective timestamptz,
  onset timestamptz,
  expires timestamptz,
  onset_fallback_used boolean not null default false,
  onset_fallback_note text,
  headline text,
  description text,
  instruction text,
  area_desc text,
  official_url varchar(400),
  escalation_mode varchar(1) not null constraint ck_incidents_mode check (escalation_mode in ('A','B','C','D')),
  requires_dispatch_approval boolean not null default false,
  interval_override_seconds integer,
  created_by_user_id varchar(36) references users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  closed_at timestamptz,
  closed_by_user_id varchar(36) references users(id) on delete set null,
  close_note text,
  -- Real incidents can never be created as demo and vice versa through a source mismatch.
  constraint ck_incidents_demo_source check (not (is_demo and source = 'live'))
);
create index ix_incidents_status on incidents (status, is_demo);
create index ix_incidents_cap_identifier on incidents (cap_identifier);

create table incident_wards (
  id varchar(36) primary key,
  incident_id varchar(36) not null references incidents(id) on delete cascade,
  ward_id varchar(36) not null references wards(id) on delete cascade,
  match_method varchar(20) not null,
  match_note text,
  unique (incident_id, ward_id)
);
create index ix_incident_wards_incident_id on incident_wards (incident_id);
create index ix_incident_wards_ward_id on incident_wards (ward_id);

create table deliveries (
  id varchar(36) primary key,
  incident_id varchar(36) not null references incidents(id) on delete cascade,
  resident_id varchar(36) not null references residents(id) on delete cascade,
  status varchar(12) not null default 'PENDING'
    constraint ck_deliveries_status check (status in ('PENDING','NO_REPLY','SAFE','HELP','UNREACHABLE')),
  channels jsonb not null default '[]'::jsonb,
  accessibility_modes jsonb not null default '[]'::jsonb,
  alerted_at timestamptz,
  seen_at timestamptz,
  replied_at timestamptz,
  reply_channel varchar(20),
  resolved_at timestamptz,
  resolved_by varchar(30),
  help_requested_at timestamptz,
  escalation_level integer not null default 0,
  escalation_step varchar(40) not null default 'alerted',
  next_action_at timestamptz,                        -- persisted deadline; survives worker restarts
  needs_operator boolean not null default false,
  needs_rescue boolean not null default false,
  rescue_reason text,
  override_reason text,
  reminders_sent integer not null default 0,
  version integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint uq_delivery_incident_resident unique (incident_id, resident_id)
);
create index ix_deliveries_due on deliveries (next_action_at, status);
create index ix_deliveries_incident_status on deliveries (incident_id, status);
-- Hot path for the escalation worker: only rows with a pending deadline.
create index ix_deliveries_pending_due on deliveries (next_action_at) where next_action_at is not null;

create table tasks (
  id varchar(36) primary key,
  incident_id varchar(36) not null references incidents(id) on delete cascade,
  delivery_id varchar(36) not null references deliveries(id) on delete cascade,
  resident_id varchar(36) not null references residents(id) on delete cascade,
  kind varchar(20) not null
    constraint ck_tasks_kind check (kind in ('neighbour_check','volunteer_assist','preevac_assist')),
  status varchar(20) not null constraint ck_tasks_status check (status in
    ('PENDING_APPROVAL','ASSIGNED','ACCEPTED','REACHED','CANT_GO','CANCELLED','REJECTED','COMPLETED')),
  assignee_user_id varchar(36) references users(id) on delete set null,
  volunteer_id varchar(36) references volunteers(id) on delete set null,
  reason text not null,
  outcome varchar(30),
  outcome_note text,
  cant_go_reason varchar(30),
  distance_m double precision,
  est_walk_minutes double precision,
  attempt_no integer not null default 1,
  approved_by_user_id varchar(36) references users(id) on delete set null,
  approved_at timestamptz,
  accepted_at timestamptz,
  reached_at timestamptz,
  closed_at timestamptz,
  created_at timestamptz not null default now(),
  version integer not null default 1,
  constraint ck_tasks_cant_go_reason check (status <> 'CANT_GO' or cant_go_reason is not null)
);
create index ix_tasks_incident_id on tasks (incident_id);
create index ix_tasks_assignee_status on tasks (assignee_user_id, status);
-- At most one open task of each kind per delivery: prevents duplicate assignment under concurrency.
create unique index uq_tasks_open_per_delivery_kind on tasks (delivery_id, kind)
  where status in ('PENDING_APPROVAL','ASSIGNED','ACCEPTED');

create table notification_attempts (
  id varchar(36) primary key,
  delivery_id varchar(36) references deliveries(id) on delete cascade,
  task_id varchar(36) references tasks(id) on delete cascade,
  incident_id varchar(36) references incidents(id) on delete cascade,
  channel varchar(12) not null constraint ck_attempts_channel check (channel in ('push','sms','in_app')),
  recipient_kind varchar(20) not null,
  recipient_user_id varchar(36) references users(id) on delete set null,
  recipient_phone varchar(20),
  body text,
  status varchar(12) not null constraint ck_attempts_status check (status in ('queued','sent','failed','blocked')),
  title varchar(200),
  data jsonb not null default '{}'::jsonb,
  provider varchar(20),
  provider_message_id varchar(120),
  error text,
  retries integer not null default 0,
  next_retry_at timestamptz,
  round varchar(30) not null default 'initial',
  idempotency_key varchar(200) not null unique,
  created_at timestamptz not null default now(),
  sent_at timestamptz
);
create index ix_notification_attempts_delivery_id on notification_attempts (delivery_id);
create index ix_notification_attempts_task_id on notification_attempts (task_id);
create index ix_notification_attempts_incident_id on notification_attempts (incident_id);
create index ix_notification_attempts_recipient_phone on notification_attempts (recipient_phone);
create index ix_attempts_queue on notification_attempts (status, next_retry_at);

create table incident_timeline (
  id varchar(36) primary key,
  incident_id varchar(36) not null references incidents(id) on delete cascade,
  delivery_id varchar(36) references deliveries(id) on delete cascade,
  resident_id varchar(36) references residents(id) on delete cascade,
  event_type varchar(40) not null,
  message text not null,
  actor_kind varchar(20) not null,
  actor_user_id varchar(36) references users(id) on delete set null,
  data jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);
create index ix_timeline_incident_time on incident_timeline (incident_id, created_at);
create index ix_incident_timeline_delivery_id on incident_timeline (delivery_id);

create table audit_log (
  id varchar(36) primary key,
  actor_user_id varchar(36) references users(id) on delete set null,
  actor_role varchar(20),
  action varchar(60) not null,
  entity_type varchar(40) not null,
  entity_id varchar(64),
  reason text,
  before jsonb,
  after jsonb,
  created_at timestamptz not null default now()
);
create index ix_audit_entity on audit_log (entity_type, entity_id);
create index ix_audit_log_actor_user_id on audit_log (actor_user_id);
create index ix_audit_log_created_at on audit_log (created_at);

create table device_registrations (
  id varchar(36) primary key,
  user_id varchar(36) not null references users(id) on delete cascade,
  fcm_token varchar(400) not null,
  platform varchar(20) not null,
  created_at timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  unique (user_id, fcm_token)
);
create index ix_device_registrations_user_id on device_registrations (user_id);

create table alert_templates (
  id varchar(36) primary key,
  hazard_type varchar(60) not null,
  language varchar(5) not null,
  style varchar(20) not null,
  title varchar(200) not null,
  body text not null constraint ck_template_has_official_text check (position('{headline}' in body) > 0),
  pictogram varchar(40),
  audio_asset_url varchar(400),
  is_active boolean not null default true,
  updated_at timestamptz not null default now(),
  unique (hazard_type, language, style)
);

create table sms_inbound (
  id varchar(36) primary key,
  provider_message_id varchar(120) not null unique,  -- webhook idempotency
  from_phone varchar(20) not null,
  body text not null,
  parsed_action varchar(20),
  result varchar(40) not null,
  delivery_id varchar(36) references deliveries(id) on delete set null,
  task_id varchar(36) references tasks(id) on delete set null,
  is_simulated boolean not null default false,
  received_at timestamptz not null default now()
);
create index ix_sms_inbound_from_phone on sms_inbound (from_phone);

create table idempotency_keys (
  id varchar(36) primary key,
  user_id varchar(36) not null references users(id) on delete cascade,
  key varchar(100) not null,
  endpoint varchar(200) not null,
  response jsonb not null,
  created_at timestamptz not null default now(),
  unique (user_id, key)
);

create table worker_heartbeats (
  worker_id varchar(80) primary key,
  job varchar(40) not null,
  last_beat_at timestamptz not null default now(),
  last_result text
);
